reference_solution.python:
class Solution:
    def numSubarrayProductLessThanK(self, nums: List[int], k: int) -> int:
        if k <= 1: return 0
        l = 0
        product = 1
        count = 0
        for r, n in enumerate(nums):
            product *= n
            while product >= k:
                product //= nums[l]
                l += 1
            count += r - l + 1
        return count

reference_solution.javascript:
function numSubarrayProductLessThanK(nums, k) {
    if (k <= 1) return 0;
    let l = 0, product = 1, count = 0;
    for (let r = 0; r < nums.length; r++) {
        product *= nums[r];
        while (product >= k) {
            product /= nums[l];
            l++;
        }
        count += r - l + 1;
    }
    return count;
}
